class Solution {
public:
    int maximumDifference(vector<int>& nums) {

        int maxdif = -1; 
        int minel = nums[0];

        if(nums[0] < nums[1])
                maxdif = nums[1] - nums[0];

        if(nums.size() == 2){

            return maxdif;

        }

        for(int i = 1; i < nums.size() - 1; i++){

            minel = min(minel, nums[i]);
            int j = i + 1;

            if(nums[j] > minel)
                maxdif = max(maxdif, nums[j] - minel);

        }

        return maxdif;
    }
};

class Solution(object):
    def maximumDifference(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        n = len(nums)
        prev_min = nums[0]
        ans = -float("inf")
        for i in range(1, n):
            ans = max(ans, nums[i] - prev_min)
            prev_min = min(prev_min, nums[i])
        if ans <= 0:
            return -1
        else:
            return ans
